// The OutSystems UI catalog of ssam_discover: for an intent that creates or builds screens, the answer carries an
// `outsystemsUi` section listing the patterns of the OutSystems UI library of the lane and app type (names and one
// line each), so the author composes the screen from library blocks instead of hand-built containers, CSS or
// JavaScript; `expand osui:<Category>` / `osui:<Pattern>` returns inputs, events, placeholders and the instance op.
// Data: outsystems-ui/catalog.json, generated by outsystems-ui/generate.mjs from the library catalogs in the
// repository (hashes inside). Pure: no I/O besides reading that file once; the budget lives in discovery.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { normalize } from './catalog.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
export const OSUI_CATALOG_FILE = path.join(here, 'outsystems-ui', 'catalog.json');
export const OSUI_LEVELS = ['lines', 'names', 'counts'];
export const APP_TYPES = { odc: ['odc-reactive', 'odc-mobile'], o11: ['o11-reactive', 'o11-mobile', 'o11-traditional'] };

let cached = null;
export function loadOsuiCatalog(file = OSUI_CATALOG_FILE) {
  if (cached?.file === file) return cached.catalog;
  const catalog = JSON.parse(fs.readFileSync(file, 'utf8').replace(/^﻿/, ''));
  cached = { file, catalog };
  return catalog;
}

// A package without the data file answers without the section instead of failing the discovery.
export function osuiCatalogAvailable(file = OSUI_CATALOG_FILE) { try { return !!loadOsuiCatalog(file).libraries?.length; } catch { return false; } }

// ---- which intents get the section: one that creates or builds screens (a direct match of a screen-building
// capability, or a screen word), never one that only renames, deletes, moves or replaces.
export const SCREEN_CAPABILITIES = ['ui.screen', 'ui.html-page', 'ui.screen-spec', 'ui.html-visual', 'ui.block-instance', 'ui.form', 'ui.list', 'ui.dropdown-search', 'ui.traditional-screen'];
const SCREEN_WORDS = new Set(['tela', 'telas', 'pagina', 'paginas', 'screen', 'screens', 'page', 'pages', 'formulario', 'formularios', 'form', 'forms', 'dashboard', 'dashboards',
  'painel', 'paineis', 'layout', 'layouts', 'card', 'cards', 'cartao', 'cartoes', 'menu', 'menus', 'sidebar', 'galeria', 'gallery', 'wizard', 'aba', 'abas', 'tabs', 'accordion',
  'carrossel', 'carousel', 'modal', 'popup', 'deck', 'decks', 'slider', 'sliders']);
// "screen action", "ação de tela", "page action": logic, not a screen.
const ACTION_WORDS = new Set(['action', 'actions', 'acao', 'acoes']);
const CREATION_WORDS = new Set(['criar', 'crie', 'cria', 'criando', 'create', 'creating', 'new', 'novo', 'nova', 'novos', 'novas', 'add', 'adicionar', 'adicione', 'acrescentar',
  'incluir', 'inclua', 'montar', 'monte', 'construir', 'construa', 'build', 'building', 'desenhar', 'desenhe', 'design', 'fazer', 'faca', 'make', 'gerar', 'gere', 'generate',
  'exibir', 'exiba', 'mostrar', 'mostre', 'show', 'display', 'colocar', 'coloque', 'compor', 'implementar', 'implement']);
const REFACTOR_WORDS = new Set(['renomear', 'renomeie', 'rename', 'apagar', 'apague', 'delete', 'excluir', 'exclua', 'remover', 'remova', 'remove', 'mover', 'mova', 'move',
  'reordenar', 'reorder', 'duplicar', 'duplicate', 'substituir', 'substitua', 'replace', 'trocar']);
const GENERIC_WHY = new Set(['data', 'date', 'time', 'datetime', 'text', 'value', 'values', 'field', 'name', 'type', 'record']);
const words = text => normalize(text).split(/[^a-z0-9]+/).filter(Boolean);
export function screenWords(intent) {
  const w = words(intent);
  return w.filter((t, i) => SCREEN_WORDS.has(t) && !ACTION_WORDS.has(w[i + 1] ?? '') && !(ACTION_WORDS.has(w[i - 2] ?? '') && w[i - 1] === 'de'));
}
export function isScreenIntent(intent, matches = []) {
  const w = words(intent);
  // A direct match named only by generic words ("atributo Data" -> ui.html-page by data/date) is not a screen.
  const direct = (matches ?? []).filter(m => m.via === 'match' && SCREEN_CAPABILITIES.includes(m.id) && (!Array.isArray(m.why) || m.why.some(w => !GENERIC_WHY.has(normalize(w))))).map(m => m.id);
  const nouns = screenWords(intent);
  if (!direct.length && !nouns.length) return false;
  const refactor = w.some(t => REFACTOR_WORDS.has(t)); const create = w.some(t => CREATION_WORDS.has(t));
  return !(refactor && !create);
}

// ---- app type: from the capture when the answer read one, else from the intent's words, else every type of the lane.
const MOBILE_WORDS = new Set(['mobile', 'movel', 'moveis', 'celular', 'phone', 'smartphone', 'tablet', 'android', 'ios', 'nativo', 'native']);
const REACTIVE_WORDS = new Set(['reactive', 'reativa', 'reativo', 'reativas', 'web', 'responsive', 'responsiva']);
const TRADITIONAL_WORDS = new Set(['traditional', 'tradicional', 'webresponsive']);
export function appTypesFromIntent(lane, intent) {
  const w = new Set(words(intent));
  const has = set => [...set].some(t => w.has(t));
  const out = [];
  const traditional = lane === 'o11' && has(TRADITIONAL_WORDS);
  // "traditional web" names one app type: there "web" is not a Reactive word.
  if (has(traditional ? new Set([...REACTIVE_WORDS].filter(t => t !== 'web' && t !== 'responsive')) : REACTIVE_WORDS)) out.push(lane + '-reactive');
  if (has(MOBILE_WORDS)) out.push(lane + '-mobile');
  if (traditional) out.push('o11-traditional');
  return out;
}
// kinds is a list of {kind, count} the capture answered (context reads or map probes): Web* elements make an O11 module
// Traditional, Mobile* elements Reactive or Mobile (one library, the kinds do not tell the two apart).
export function appTypesFromKinds(lane, kinds) {
  const present = prefix => kinds.some(k => String(k.kind).startsWith(prefix) && (k.count ?? 0) > 0);
  if (lane === 'o11' && present('Web')) return ['o11-traditional'];
  if (present('Mobile')) return lane === 'o11' ? ['o11-reactive', 'o11-mobile'] : ['odc-reactive', 'odc-mobile'];
  return [];
}

// ---- the patterns an intent names: by the pattern's own name ("tabs" -> Tabs, "stackedcards" -> StackedCards) or by a
// synonym of the catalog ("deck", "swipe" -> StackedCards; "slider", "range" -> RangeSlider), in the libraries of the lane
// and app types. Each entry says the word that named it and the expansion that returns the whole pattern.
export function namedPatterns(lane, intent, appTypes = null, catalog = loadOsuiCatalog()) {
  const w = words(intent); const out = [];
  const synonyms = catalog.synonyms ?? {};
  for (const g of librariesFor(catalog, lane, appTypes)) for (const p of g.library.patterns) {
    const own = p.name.toLowerCase();
    const via = w.find(t => t === own || t === own + 's' || synonyms[t] === p.name);
    if (!via) continue;
    const found = out.find(x => x.pattern === p.name);
    if (found) { found.libraries.push(libraryLabel(g.library)); continue; }
    out.push({ pattern: p.name, category: p.category, line: p.line ?? null, via, libraries: [libraryLabel(g.library)], expand: `osui:${p.name}` });
  }
  return out.slice(0, 6);
}

// ---- the section, at a level: lines (name + one line per pattern), names (names per category), counts.
function librariesFor(catalog, lane, appTypes) {
  const wanted = (appTypes?.length ? appTypes : APP_TYPES[lane] ?? []).filter(t => catalog.appTypes[t]?.lane === lane);
  const groups = [];
  for (const t of wanted) {
    const id = catalog.appTypes[t].library;
    const g = groups.find(x => x.id === id);
    if (g) g.appTypes.push(t); else groups.push({ id, appTypes: [t], library: catalog.libraries.find(l => l.id === id) });
  }
  return groups.filter(g => g.library);
}
const libraryLabel = l => `${l.name} ${l.version ?? 'revision ' + l.revision}`;
export function osuiSection(request, level = 'lines', catalog = loadOsuiCatalog()) {
  const { lane, appTypes, from } = request;
  const groups = librariesFor(catalog, lane, appTypes);
  const libraries = groups.map(({ library: l, appTypes: types }) => {
    const categories = {};
    for (const p of l.patterns) {
      if (level === 'counts') { categories[p.category] = (categories[p.category] ?? 0) + 1; continue; }
      (categories[p.category] ??= []).push(level === 'lines' ? (p.line ? `${p.name}: ${p.line}` : `${p.name}: (no description in the library)`) : p.name);
    }
    if (level === 'names') for (const k of Object.keys(categories)) categories[k] = categories[k].join(', ');
    return { library: libraryLabel(l), appTypes: types, element: l.element, patterns: l.patterns.length, categories };
  });
  // The patterns the intent named stay at every level (one line each above counts): they are what was asked.
  const named = (request.named ?? []).map(n => (level === 'counts' ? { pattern: n.pattern, via: n.via, expand: n.expand } : { pattern: n.pattern, category: n.category, line: n.line, via: n.via, expand: n.expand }));
  return {
    ...(level === 'counts' ? {} : { why: 'screen-building intent: compose the screen from these OutSystems UI patterns (library blocks) before custom containers, CSS or JavaScript' }),
    lane, appTypes: groups.flatMap(g => g.appTypes), appTypeFrom: from, level, ...(named.length ? { named } : {}), libraries,
    expand: `ssam_discover {lane:"${lane}", expand:"osui:<Category>,osui:<Pattern>"}: description, inputs, events, placeholders, instance op` + (level === 'lines' ? '' : '; osui:<appType> lists every pattern with one line'),
  };
}

// ---- expansion: osui:<Category> | osui:<Pattern> | osui:<appType> | osui:<appType>/<Category|Pattern>
function brief(p) { return { name: p.name, category: p.category, line: p.line ?? null, ...(p.descriptionMissing ? { descriptionMissing: true } : {}), inputs: (p.inputs ?? []).map(i => `${i.name}: ${i.type}${i.mandatory ? ' (mandatory)' : ''}`), events: (p.events ?? []).map(e => `${e.name}(${(e.params ?? []).join(', ')})${e.mandatory ? ' (mandatory)' : ''}`), placeholders: (p.placeholders ?? []).map(x => x.name), ...(p.docs ? { docs: p.docs } : {}) }; }
const bytesOf = value => Buffer.byteLength(JSON.stringify(value), 'utf8');
export function osuiExpansion(lane, selector, { capBytes = 1 << 20, catalog = loadOsuiCatalog() } = {}) {
  const raw = String(selector ?? '').trim();
  const slash = raw.indexOf('/');
  const typeHead = slash > 0 ? raw.slice(0, slash) : (catalog.appTypes[raw.toLowerCase()] ? raw : null);
  const appType = typeHead ? typeHead.toLowerCase() : null;
  const term = slash > 0 ? raw.slice(slash + 1) : (appType ? '' : raw);
  if (appType && catalog.appTypes[appType]?.lane !== lane) return { error: `unknown app type '${typeHead}' on lane ${lane}`, known: APP_TYPES[lane] };
  const groups = librariesFor(catalog, lane, appType ? [appType] : null);
  const key = term.toLowerCase();
  const pick = wanted => { const out = []; for (const g of groups) { const l = g.library; const patterns = !wanted ? l.patterns : l.patterns.filter(p => p.category.toLowerCase() === wanted || p.name.toLowerCase() === wanted); if (patterns.length) out.push({ g, l, patterns }); } return out; };
  let found = pick(key);
  // A word of the catalog's synonyms ("deck", "slider") answers the pattern it stands for.
  const synonym = !found.length && key ? catalog.synonyms?.[key] ?? null : null;
  if (synonym) found = pick(synonym.toLowerCase());
  if (!found.length) return { error: `no OutSystems UI category or pattern '${term || raw}' on lane ${lane}`, known: { categories: [...new Set(groups.flatMap(g => g.library.categories))], appTypes: APP_TYPES[lane] } };
  // The richest form that fits the cap: whole entries, then one line + names of inputs/events/placeholders, then one
  // line each, then names.
  const forms = [['full', p => p], ['brief', brief], ['lines', p => `${p.name} [${p.category}]: ${p.line ?? '(no description in the library)'}`], ['names', p => p.name]];
  for (const [level, shape] of forms) {
    const whole = level === 'full' || level === 'brief';
    const libraries = found.map(({ g, l, patterns }) => ({ library: libraryLabel(l), appTypes: g.appTypes, producer: l.producer, element: l.element,
      ...(whole ? { key: l.key, instance: l.instance, reference: l.reference, source: l.source } : {}),
      ...(whole && l.certified ? { certified: `every pattern below is instanced on the fixtures ${l.certified.fixtures.join(', ')} (${l.certified.by})` } : {}),
      ...(whole && l.capturedFrom ? { capturedFrom: l.capturedFrom } : {}), patterns: patterns.map(shape) }));
    const out = { lane, selector: raw, ...(synonym ? { synonym: { word: key, pattern: synonym } } : {}), level, libraries };
    if (level !== 'full') out.note = `reduced to ${level} by the byte budget: ask for one pattern (osui:<Pattern>) for the whole entry`;
    if (bytesOf(out) <= capBytes || level === 'names') return out;
  }
  return null;
}
